stem:
What happens when this script runs?

```js
greet();

function greet() {
  console.log('hi');
}
```

What happens when this script runs?

```js
sayHi();

var sayHi = function () {
  console.log('hi');
};
```

Assuming nothing else is declared, what does this log?

```js
if (true) {
  let x = 1;
  var y = 2;
}
console.log(typeof x, y);
```

What does this log?

```js
function makeCounter() {
  let count = 0;
  return {
    inc() {
      return ++count;
    },
  };
}

const c = makeCounter();
c.inc();
c.inc();
console.log(c.inc(), c.count);
```

Put these steps in the order they happen when this runs:

```js
function User(name) {
  this.name = name;
}
const u = new User('Ada');
```

Older scripts often wrap all their code like this. What is the main reason?

```js
(function () {
  var config = { debug: false };
  // ...the rest of the script
})();
```

What does this log?

```js
const fns = [];
let i;
for (i = 0; i < 3; i++) {
  fns.push(() => i);
}
console.log(fns.map((f) => f()));
```

What happens when this runs?

```js
let x = 1;
{
  console.log(x);
  let x = 2;
}
```

Assuming `a` is never declared anywhere, what happens when this runs?

```js
console.log(typeof a);
console.log(typeof b);
let b = 1;
```

This logs `undefined` (or throws in strict mode) instead of `Ada`:

```js
const obj = {
  name: 'Ada',
  hello() {
    console.log(this.name);
  },
};
setTimeout(obj.hello, 0);
```

Which two replacements make it log `Ada`? (Choose two.)

What does this log?

```js
'use strict';
const o = {
  name: 'o',
  regular() {
    return [1].map(function () {
      return this?.name;
    });
  },
  arrow() {
    return [1].map(() => this.name);
  },
};
console.log(o.regular(), o.arrow());
```

What does this log?

```js
function mul(a, b) {
  return a * b;
}
const double = mul.bind(null, 2);
console.log(double(5), double.length);
```

What does this log?

```js
function curry(fn) {
  return function curried(...args) {
    return args.length >= fn.length
      ? fn(...args)
      : (...more) => curried(...args, ...more);
  };
}

const sum3 = curry((a, b, c) => a + b + c);
console.log(sum3(1, 2)(3, 4));
```

What does this log?

```js
var x = 1;

function f(a = () => x) {
  var x = 2;
  return a();
}

console.log(f());
```

What happens when this runs?

```js
function f(a = b, b = 2) {
  return a;
}
console.log(f());
```

In sloppy mode (no `'use strict'`), what does this log?

```js
function f(a) {
  arguments[0] = 99;
  return a;
}
function g(a = 0) {
  arguments[0] = 99;
  return a;
}
console.log(f(1), g(1));
```

What does this log?

```js
function Point(x, y) {
  this.x = x;
  this.y = y;
}
const P = Point.bind({ x: 100 }, 1);
const p = new P(2);
console.log(p.x, p.y, p instanceof Point);
```

After `destroy()` runs, clicking the button still logs `clicked`. Why?

```js
class Menu {
  constructor(button) {
    this.button = button;
    button.addEventListener('click', this.onClick.bind(this));
  }
  onClick() {
    console.log('clicked');
  }
  destroy() {
    this.button.removeEventListener('click', this.onClick.bind(this));
  }
}
```

What does this return?

```js
function outer() {
  const inner = () => arguments[0];
  return inner('x');
}
outer('y');
```

What does this log? Type the exact string.

```js
const g = (function inner() {}).bind(null);
console.log(g.name);
```

In sloppy mode, what does this log?

```js
const fact = function f(n) {
  f = null;
  return n <= 1 ? 1 : n * f(n - 1);
};
console.log(fact(3));
```

`fn` is a pure function of all its arguments. Which three are real bugs in this memoize helper? (Choose three.)

```js
function memoize(fn) {
  const cache = {};
  return (...args) => (cache[args[0]] ??= fn(...args));
}
```

In a sloppy-mode classic script in a browser or Node.js, what does this log?

```js
console.log(typeof f);
{
  function f() {}
}
console.log(typeof f);
```

What does this log?

```js
function Base() { this.kind = new.target.name; }
function Child() { return Reflect.construct(Base, [], Child); }
Child.prototype = Object.create(Base.prototype);

const c = new Child();
console.log(c.kind, c instanceof Child, c instanceof Base);
```

In a sloppy-mode classic script, what does `f()` return?

```js
var x = 'global';

function f() {
  var x = 'local';
  return [eval('x'), (0, eval)('x')];
}
```

This code is in an ES module. What does it log?

```js
const o = {
  a: () => this,
  b() {
    return (() => this)();
  },
};
console.log(o.a(), o.b() === o);
```

What does this log?

```js
const fns = [];
for (let i = 0, get = () => i; i < 3; i++) {
  fns.push(get);
}
console.log(fns.map((f) => f()));
```

What does this log? Type a number.

```js
const curry = (fn) =>
  function c(...a) {
    return a.length >= fn.length ? fn(...a) : (...b) => c(...a, ...b);
  };

const f = curry((a, b = 10, c) => a + b + (c ?? 0));
console.log(f(1));
```

What does this log?

```js
var a = 1;

function b() {
  a = 10;
  return;
  function a() {}
}

b();
console.log(a);
```

Given this strict-mode code, which three expressions return `true`? (Choose three.)

```js
'use strict';
function who() {
  return this === obj;
}
const obj = { who };
```
